<?php $this->setLayout(''); require __DIR__.'/_layout.php'; ?><section class="panel"><p class="muted">Only key prefixes are shown. Secret API keys are never displayed in this console.</p><table><thead><tr><th>Workspace</th><th>Label / prefix</th><th>Mode</th><th>Last used</th><th>Created</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= htmlspecialchars($r['workspace_name']) ?></td><td><?= htmlspecialchars($r['label']) ?><br><code><?= htmlspecialchars($r['key_prefix']) ?></code></td><td><?= htmlspecialchars($r['mode']) ?></td><td><?= htmlspecialchars($r['last_used_at']??'Never') ?></td><td><?= htmlspecialchars($r['created_at']) ?></td><td><span class="pill <?= $r['revoked_at']?'bad':'' ?>"><?= $r['revoked_at']?'revoked':'active' ?></span></td><td><?php if(!$r['revoked_at']): ?><form method="post" action="/admin/platform/api-keys/<?= (int)$r['id'] ?>/revoke" onsubmit="return confirm('Revoke this API key? Requests using it will stop working.')"><button class="btn warn" type="submit">Revoke</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty">No API keys found.</td></tr><?php endif; ?></tbody></table></section></main></div></body></html>
